import type { Level } from "../types";

export type PType = "mcq" | "multi" | "order" | "match" | "numeric" | "code" | "diagram" | "recall";

/** A practice item as generated by tools/build-content.mjs (already in one locale). */
export interface PItem {
  id: string;
  c: string; // concept id
  type: PType;
  auto?: 1;
  prompt: string;
  explain?: string;
  options?: { text: string; why?: string }[];
  answer?: number | string; // option index (mcq/code), number (numeric), markdown (recall)
  answers?: number[];
  steps?: string[];
  pairs?: { left: string; right: string }[];
  tolerance?: number;
  unit?: string;
  lang?: string;
  code?: string;
  blanks?: { node: string; label: string }[];
  bank?: string[];
}

export interface PModule { id: string; t: string; c: string[] }
export interface PPhase { id: string; t: string; g: string; modules: PModule[] }
export interface PracticeData {
  meta: Record<string, { d: string; t: string; l: Level }>;
  phases: PPhase[];
  items: PItem[];
}

/** What the learner did, always expressed in ORIGINAL indexes (never display positions). */
export type Response =
  | { type: "mcq" | "code"; choice: number }
  | { type: "multi"; choices: number[] }
  | { type: "order"; order: number[] }
  | { type: "match"; map: number[] }
  | { type: "numeric"; value: number }
  | { type: "diagram"; fill: Record<string, string> }
  | { type: "recall"; self: 1 | 2 | 3 | 4 };

/** 0 = guessing, 1 = think so, 2 = sure. */
export type Confidence = 0 | 1 | 2;
